{
  "service": "gateway",
  "description": "gateway edge proxy",
  "listen": {
    "address": "127.0.0.1",
    "port": 8080
  },
  "tls": {
    "enabled": true,
    "verify_upstream": true,
    "min_version": "1.2"
  },
  "logging": {
    "level": "info",
    "format": "json",
    "sample_rate_pct": 100
  },
  "limits": {
    "max_body_kib": 512,
    "max_connections": 2048,
    "idle_timeout_s": 60
  },
  "features": {
    "compression": true,
    "http2": true,
    "request_ids": true
  },
  "upstreams": [
    {
      "name": "reviews",
      "host": "reviews.internal",
      "port": 9518,
      "weight": 10,
      "health_check": "/healthz"
    },
    {
      "name": "accounts",
      "host": "accounts.internal",
      "port": 7428,
      "weight": 2,
      "health_check": "/healthz"
    },
    {
      "name": "search",
      "host": "search.internal",
      "port": 8390,
      "weight": 8,
      "health_check": "/healthz"
    },
    {
      "name": "payments",
      "host": "payments.internal",
      "port": 9179,
      "weight": 8,
      "health_check": "/healthz"
    },
    {
      "name": "carts",
      "host": "carts.internal",
      "port": 9112,
      "weight": 6,
      "health_check": "/healthz"
    }
  ],
  "routes": [
    {
      "path": "/api/v1/carts/items",
      "upstream": "carts",
      "methods": [
        "GET"
      ],
      "timeout_ms": 3000,
      "retries": 0
    },
    {
      "path": "/api/v1/accounts/history",
      "upstream": "accounts",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 5000,
      "retries": 2
    },
    {
      "path": "/api/v1/search/history",
      "upstream": "search",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 2500,
      "retries": 3
    },
    {
      "path": "/api/v1/carts/labels",
      "upstream": "carts",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 1000,
      "retries": 3
    },
    {
      "path": "/api/v1/accounts/export",
      "upstream": "accounts",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 2000,
      "retries": 2
    },
    {
      "path": "/api/v1/accounts/quotes",
      "upstream": "accounts",
      "methods": [
        "GET"
      ],
      "timeout_ms": 1000,
      "retries": 1
    },
    {
      "path": "/api/v1/payments/quotes",
      "upstream": "payments",
      "methods": [
        "GET"
      ],
      "timeout_ms": 1500,
      "retries": 1
    },
    {
      "path": "/api/v1/carts/settings",
      "upstream": "carts",
      "methods": [
        "GET"
      ],
      "timeout_ms": 3000,
      "retries": 2
    },
    {
      "path": "/api/v1/reviews/export",
      "upstream": "reviews",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 1500,
      "retries": 3
    }
  ]
}

